const Login = () => {
  const { updateUserInfo, setUserInfo, isInitialized } =
    useContext(AuthContext);
  const [loginData, setLoginData] = useState({
    username: "",
    pass: "",
  });

  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [isRemembered, setIsRemembered] = useState(false);
  const [debugInfo, setDebugInfo] = useState("");
  const navigate = useNavigate();

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };
  const loadCurrentUserProfile = async (directUserData) => {
    try {
      setDebugInfo("   loading Profile data...");

      const extraData = await ArticleServices.getCurrentUsrProfile({
        userId: directUserData.user_id,
        credentials: directUserData.ps,
      });

      if (!extraData || !extraData.profilePictureUrl) {
        setDebugInfo("❌ error: data fetched but image url is empty  !");
      } else {
        setDebugInfo(
          `✅   image has been found : ${extraData.profilePictureUrl.substring(
            0,
            30
          )}...`
        );
      }

      const fullUserData = {
        ...directUserData,
        ...extraData,
      };

      localStorage.setItem("theUserData", JSON.stringify(fullUserData));
      setUserInfo(fullUserData);

      setTimeout(() => {
        navigate("/", { replace: true });
      }, 3000);
    } catch (err) {
      setDebugInfo(`❌ tech error : ${err.message}`);
      console.error(err);
    }
  };
  const callAPI = () => {
    setLoading(true);
    setError(null);

    fetch(`https://tamkeen-dev.com/api/user/login?_format=json`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: loginData.username,
        pass: loginData.pass,
      }),
    })
      .then((res) => {
        if (!res.ok) throw new Error(" username or password is incorrect");
        return res.json();
      })
      .then((data) => {
        const userData = {
          username: data.current_user.name,
          user_id: data.current_user.uid,
          csrf_token: data.csrf_token,
          logout_token: data.logout_token,
          ps: btoa(`${loginData.username}:${loginData.pass}`),
        };
        loadCurrentUserProfile(userData);
      })
      .catch((err) => {
        setError(err.message);
        setLoading(false);
      });
  };

  if (isInitialized) {
    return <></>;
  }

  return (
    <>
      <Navigation />
      <div className="d-flex min-vh-100">
        <Row className="w-100 m-0">
          <Col
            lg={5}
            className="auth-image-col d-none d-lg-flex align-items-center justify-content-center p-5"
          >
            <img
              src={img}
              alt="Login Illustration"
              className="img-fluid login-img"
            />
          </Col>

          <Col
            lg={7}
            className="auth-form-col d-flex align-items-center justify-content-center p-4"
          >
            <div className="login-box p-3 w-100" style={{ maxWidth: "648px" }}>
              <h2 className="mb-5 login-title">Sign in to your account</h2>

              {error && <div className="mb-3 alert alert-danger">{error}</div>}

              {debugInfo && (
                <div
                  className="mb-3 alert alert-info"
                  style={{ fontSize: "12px", direction: "ltr" }}
                >
                  <strong>Debug Info:</strong> {debugInfo}
                </div>
              )}
              <form
                className="signin-form"
                onSubmit={(e) => {
                  e.preventDefault();
                  callAPI();
                }}
              >
                <div className="mb-3">
                  <label htmlFor="Username" className="form-label mb-1">
                    Username
                  </label>
                  <input
                    id="Username"
                    type="text"
                    className="form-control"
                    required
                    placeholder="Username"
                    onInput={(e) =>
                      setLoginData({ ...loginData, username: e.target.value })
                    }
                  />
                </div>

                <div className="mb-3">
                  <label htmlFor="password" className="form-label mb-1">
                    Password
                  </label>
                  <div className="password-input-container position-relative">
                    <input
                      id="password"
                      type={showPassword ? "text" : "password"}
                      className="form-control"
                      placeholder="Password"
                      required
                      onInput={(e) =>
                        setLoginData({ ...loginData, pass: e.target.value })
                      }
                    />
                    <span
                      className="password-toggle position-absolute end-0 top-50 translate-middle-y me-3"
                      onClick={togglePasswordVisibility}
                      style={{ cursor: "pointer" }}
                    >
                      <EyeIcon />
                    </span>
                  </div>
                </div>

                <div className="mb-3 d-flex justify-content-between align-items-center">
                  <div className="form-check">
                    <input
                      className="form-check-input"
                      type="checkbox"
                      id="rememberMe"
                      checked={isRemembered}
                      onChange={(e) => setIsRemembered(e.target.checked)}
                    />
                    <label
                      className="form-check-label mb-1"
                      htmlFor="rememberMe"
                    >
                      Remember me
                    </label>
                  </div>

                  <button
                    className="btn py-2 signin-btn"
                    type="submit"
                    disabled={
                      loading ||
                      loginData.username.length < 3 ||
                      loginData.pass.length < 6
                    }
                  >
                    {loading ? (
                      <i>Signing in...</i>
                    ) : (
                      <>
                        Sign In <ArrowIcon />
                      </>
                    )}
                  </button>
                </div>

                <div className="separator-text text-center mt-4 mb-3">
                  Or Sign In With
                </div>
                <div className="d-flex justify-content-center gap-3">
                  <Google /> <Facebook /> <Apple />
                </div>
              </form>
            </div>
          </Col>
        </Row>
      </div>
    </>
  );
};

export default Login;
